window.__PIONEER_REGISTER_TEST("TEST_HIST_SET_29", [
  {"q":"[UPSC/PCS सूची सुमेलन — संवैधानिक अधिनियम एवं प्रावधान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. चार्टर अधिनियम, 1813   |   1. प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\nB. भारतीय परिषद अधिनियम, 1909   |   2. भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\nC. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)   |   3. अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार\nD. भारतीय परिषद अधिनियम, 1892   |   4. मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य","options":["A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1"],"correct":1,"explanation":"सही सुमेलन: चार्टर अधिनियम, 1813 (भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष), भारतीय परिषद अधिनियम, 1909 (मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य), भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) (प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली), भारतीय परिषद अधिनियम, 1892 (अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार)।"},
  {"q":"[PSC/CDS युग्म पहचान — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. भारत शासन अधिनियम, 1935 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद\n2. भारत शासन अधिनियम, 1858 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\n3. भारतीय परिषद अधिनियम, 1861 : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\n4. पिट्स इंडिया एक्ट, 1784 : कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: 1784 के पिट्स इंडिया एक्ट ने पहली बार भारत में कंपनी के क्षेत्रों को 'ब्रिटिश आधिपत्य का क्षेत्र' कहा। (अन्य सही युग्म: भारत शासन अधिनियम, 1935→अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण, भारत शासन अधिनियम, 1858→कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद, भारतीय परिषद अधिनियम, 1861→मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1857 की क्रांति की शुरुआत 10 मई 1857 को कोलकाता के फोर्ट विलियम से मंगल पांडे के नेतृत्व में हुई जहाँ उन्होंने लॉर्ड डलहौजी को बंदी बनाया।\nकथन-2: 1857 में जगदीशपुर के 80 वर्षीय जमींदार बाबू कुँवर सिंह ने अंग्रेजों को कई बार हराया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (मंगल पांडे ने 29 मार्च 1857 को बैरकपुर (बंगाल) में विद्रोह किया (8 अप्रैल को फांसी), जबकि व्यापक विद्रोह की शुरुआत 10 मई 1857 को मेरठ से हुई।)। कथन-2 सत्य है (1857 में जगदीशपुर के 80 वर्षीय जमींदार बाबू कुँवर सिंह ने अंग्रेजों को कई बार हराया।)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. तत्वबोधिनी सभा (1839)   B. आंग्ल-मराठा व आंग्ल-सिख युद्ध तथा प्रमुख संधियाँ\nC. वॉरेन हेस्टिंग्स (1772-85)   D. ताना भगत आंदोलन (1914)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["ताना भगत आंदोलन (1914)","तत्वबोधिनी सभा (1839)","वॉरेन हेस्टिंग्स (1772-85)","आंग्ल-मराठा व आंग्ल-सिख युद्ध तथा प्रमुख संधियाँ"],"correct":2,"explanation":"वॉरेन हेस्टिंग्स (1772-85) (1774 ई.), आंग्ल-मराठा व आंग्ल-सिख युद्ध तथा प्रमुख संधियाँ (1818 ई.), तत्वबोधिनी सभा (1839) (1839 ई.), ताना भगत आंदोलन (1914) (1914 ई.)। अतः सर्वप्रथम वॉरेन हेस्टिंग्स (1772-85)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1857 क्रांति केंद्र एवं नेता के अंतर्गत 'प्रयागराज (इलाहाबाद)' का ऐतिहासिक संबंध 'बाबू कुँवर सिंह' से था।\nकथन-2: पुर्तगाली यूरोप से भारत आने वाले प्रथम (1498 ई.) तथा सबसे अंत में जाने वाले (1961 में ऑपरेशन विजय द्वारा गोवा मुक्ति) यूरोपीय थे।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('प्रयागराज (इलाहाबाद)' का सही संबंध 'मौलवी लियाकत अली' से था — इलाहाबाद में मौलवी लियाकत अली ने विद्रोह का नेतृत्व किया जिसे कर्नल नील ने क्रूरता से कुचला।)। कथन-2 सत्य है (पुर्तगाली यूरोप से भारत आने वाले प्रथम (1498 ई.) तथा सबसे अंत में जाने वाले (1961 में ऑपरेशन विजय द्वारा गोवा मुक्ति) यूरोपीय थे।)।"},
  {"q":"'1857 की क्रांति की शुरुआत: मंगल पांडे, मेरठ व दिल्ली' के ऐतिहासिक संदर्भ में 'तात्कालिक कारण' निम्नलिखित में से क्या है?","options":["कार्ताज-आर्मेडा-काफिला प्रणाली (समुद्री परमिट), भारत में पहला प्रिंटिंग प्रेस (गोवा, 1556), गोथिक स्थापत्य","जनरल ह्यूरोज ने रानी लक्ष्मीबाई के बारे में कहा—'भारतीय क्रांतिकारियों में यहाँ सोई हुई औरत अकेली मर्द है।' प्रयागराज में लियाकत अली ने नेतृत्व किया","महारानी विक्टोरिया की 1 नवंबर 1858 घोषणा (इलाहाबाद), कंपनी शासन समाप्त कर क्राउन शासन, भारत सचिव पद, पील आयोग (सेना में यूरोपीय अनुपात बढ़ाया)","पुरानी ब्राउन बेस राइफल की जगह एनफील्ड पी-53 राइफल में गाय-सूअर की चर्बी वाले कारतूसों का प्रयोग"],"correct":3,"explanation":"विद्रोह के समय शिक्षित मध्यम वर्ग, बड़े जमींदार (ज्यादातर), सिंधिया, होलकर, निजाम और पटियाला-जींद के शासकों ने अंग्रेजों का साथ दिया (कैनिंग ने इन्हें 'तूफान में तरंगअवरोध' कहा)।"},
  {"q":"[UPSC Prelims पैटर्न — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. जगदीशपुर (आरा) : बाबू कुँवर सिंह\n2. प्रयागराज (इलाहाबाद) : मौलवी लियाकत अली\n3. बरेली (रुहेलखंड) : मौलवी अहमदुल्ला शाह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (1857 में जगदीशपुर के 80 वर्षीय जमींदार बाबू कुँवर सिंह ने अंग्रेजों को कई बार हराया।) युग्म 2 सही (इलाहाबाद में मौलवी लियाकत अली ने विद्रोह का नेतृत्व किया जिसे कर्नल नील ने क्रूरता से कुचला।) युग्म 3 गलत (सही: बरेली (रुहेलखंड) — खान बहादुर खाँ)।"},
  {"q":"किस अधिनियम ने ईस्ट इंडिया कंपनी के राजनीतिक एवं वाणिज्यिक कार्यों को पृथक कर इंग्लैंड में 6-सदस्यीय 'बोर्ड ऑफ कंट्रोल' बनाया?","options":["गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ","संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)","कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष"],"correct":2,"explanation":"1784 के पिट्स इंडिया एक्ट ने पहली बार भारत में कंपनी के क्षेत्रों को 'ब्रिटिश आधिपत्य का क्षेत्र' कहा। गवर्नर-जनरल की परिषद के सदस्य 4 से घटाकर 3 कर दिए गए।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. वॉरेन हेस्टिंग्स (1772-85) : द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त\n2. लॉर्ड विलियम बेंटिंक (1828-35) : सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)\n3. लॉर्ड लिनलिथगो (1936-44) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल (1773 एक्ट) बने; उन्होंने कलकत्ता मदरसा (1781) की स्थापना भी की।) युग्म 2 सही (राजाराम मोहन राय के सहयोग से लॉर्ड विलियम बेंटिंक ने 1829 में सती प्रथा अवैध घोषित की।) युग्म 3 सही (लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे।)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. लॉर्ड मेयो (1869-72) : 1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण\n2. चार्ल्स मेटकाफ (1835-36) : 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना\n3. लॉर्ड रिपन (1880-84) : स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\n4. वॉरेन हेस्टिंग्स (1772-85) : 1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'वॉरेन हेस्टिंग्स (1772-85)' का सही संबंध 'द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त' से है (न कि '1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम' से)। वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल (1773 एक्ट) बने; उन्होंने कलकत्ता मदरसा (1781) की स्थापना भी की।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. देव समाज (1887)   B. अलीगढ़, देवबंद, पारसी, सिख सुधार व सामाजिक कानून (1829–1930)\nC. पिट्स इंडिया एक्ट, 1784   D. चार्ल्स मेटकाफ (1835-36)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["पिट्स इंडिया एक्ट, 1784","चार्ल्स मेटकाफ (1835-36)","अलीगढ़, देवबंद, पारसी, सिख सुधार व सामाजिक कानून (1829–1930)","देव समाज (1887)"],"correct":0,"explanation":"पिट्स इंडिया एक्ट, 1784 (1784 ई.), चार्ल्स मेटकाफ (1835-36) (1835 ई.), देव समाज (1887) (1887 ई.), अलीगढ़, देवबंद, पारसी, सिख सुधार व सामाजिक कानून (1829–1930) (1891 ई.)। अतः सर्वप्रथम पिट्स इंडिया एक्ट, 1784।"},
  {"q":"[PSC/CDS युग्म पहचान — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. लॉर्ड कैनिंग (1856-62) : 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना\n2. चार्ल्स मेटकाफ (1835-36) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन\n3. वॉरेन हेस्टिंग्स (1772-85) : द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त\n4. लॉर्ड कर्जन (1899-1905) : सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल (1773 एक्ट) बने; उन्होंने कलकत्ता मदरसा (1781) की स्थापना भी की। (अन्य सही युग्म: लॉर्ड कैनिंग (1856-62)→1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम, चार्ल्स मेटकाफ (1835-36)→1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना, लॉर्ड कर्जन (1899-1905)→बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. रेगुलेटिंग एक्ट, 1773 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n2. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\n3. चार्टर अधिनियम, 1853 : संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\n4. चार्टर अधिनियम, 1813 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'चार्टर अधिनियम, 1853' का सही संबंध 'केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता' से है (न कि 'संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)' से)। 1853 का चार्टर एक्ट चार्टर श्रृंखला का अंतिम अधिनियम था जिसने कंपनी के शासन की कोई निश्चित अवधि तय नहीं की।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1857 की क्रांति की शुरुआत 10 मई 1857 को कोलकाता के फोर्ट विलियम से मंगल पांडे के नेतृत्व में हुई जहाँ उन्होंने लॉर्ड डलहौजी को बंदी बनाया।\nकथन-2: ज्योतिबा फुले ने ब्राह्मणवादी प्रभुत्व व छुआछूत के विरोध में सत्यशोधक समाज स्थापित किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (मंगल पांडे ने 29 मार्च 1857 को बैरकपुर (बंगाल) में विद्रोह किया (8 अप्रैल को फांसी), जबकि व्यापक विद्रोह की शुरुआत 10 मई 1857 को मेरठ से हुई।)। कथन-2 सत्य है (ज्योतिबा फुले ने ब्राह्मणवादी प्रभुत्व व छुआछूत के विरोध में सत्यशोधक समाज स्थापित किया।)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. 1857 विद्रोह पर इतिहासकारों के मत व 1858 के परिणाम   B. दक्कन उपद्रव (1875) परिणाम\nC. कानपुर   D. प्रमुख राष्ट्रवादी पुस्तकें एवं आधुनिक साहित्यकार\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["प्रमुख राष्ट्रवादी पुस्तकें एवं आधुनिक साहित्यकार","1857 विद्रोह पर इतिहासकारों के मत व 1858 के परिणाम","दक्कन उपद्रव (1875) परिणाम","कानपुर"],"correct":3,"explanation":"कानपुर (1857 ई.), 1857 विद्रोह पर इतिहासकारों के मत व 1858 के परिणाम (1858 ई.), दक्कन उपद्रव (1875) परिणाम (1875 ई.), प्रमुख राष्ट्रवादी पुस्तकें एवं आधुनिक साहित्यकार (1915 ई.)। अतः सर्वप्रथम कानपुर।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. लखनऊ (अवध) : बेगम हजरत महल\n2. प्रयागराज (इलाहाबाद) : मौलवी लियाकत अली\n3. जगदीशपुर (आरा) : बाबू कुँवर सिंह\n4. बरेली (रुहेलखंड) : नाना साहेब एवं तात्या टोपे","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'बरेली (रुहेलखंड)' का सही संबंध 'खान बहादुर खाँ' से है (न कि 'नाना साहेब एवं तात्या टोपे' से)। बरेली में खान बहादुर खाँ ने स्वतंत्र सरकार की स्थापना कर 40,000 सैनिक जुटाए।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. चार्टर अधिनियम, 1833 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n2. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\n3. भारतीय परिषद अधिनियम, 1892 : अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार\n4. भारतीय परिषद अधिनियम, 1861 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'चार्टर अधिनियम, 1833' का सही संबंध 'संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)' से है (न कि 'गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ' से)। 1833 के चार्टर एक्ट से लॉर्ड विलियम बेंटिंक भारत के प्रथम गवर्नर-जनरल बने।"},
  {"q":"[PSC/CDS युग्म पहचान — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. कानपुर : नाना साहेब एवं तात्या टोपे\n2. लखनऊ (अवध) : मौलवी अहमदुल्ला शाह\n3. फैजाबाद : बाबू कुँवर सिंह\n4. जगदीशपुर (आरा) : मौलवी लियाकत अली","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: नाना साहेब (धोंधू पंत) व तात्या टोपे (रामचंद्र पांडुरंग) ने कानपुर में क्रांति का नेतृत्व किया। (अन्य सही युग्म: लखनऊ (अवध)→बेगम हजरत महल, फैजाबाद→मौलवी अहमदुल्ला शाह, जगदीशपुर (आरा)→बाबू कुँवर सिंह)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — गवर्नर-जनरल / वायसराय एवं कार्य] सूची-I को सूची-II से सुमेलित कीजिए:\nA. वॉरेन हेस्टिंग्स (1772-85)   |   1. सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)\nB. लॉर्ड विलियम बेंटिंक (1828-35)   |   2. बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना\nC. लॉर्ड डलहौजी (1848-56)   |   3. द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त\nD. लॉर्ड कॉर्नवालिस (1786-93)   |   4. व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: वॉरेन हेस्टिंग्स (1772-85) (द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त), लॉर्ड विलियम बेंटिंक (1828-35) (सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)), लॉर्ड डलहौजी (1848-56) (व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)), लॉर्ड कॉर्नवालिस (1786-93) (बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. प्रयागराज (इलाहाबाद) : मौलवी लियाकत अली\n2. बरेली (रुहेलखंड) : खान बहादुर खाँ\n3. फैजाबाद : मौलवी अहमदुल्ला शाह\n4. जगदीशपुर (आरा) : बेगम हजरत महल","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'जगदीशपुर (आरा)' का सही संबंध 'बाबू कुँवर सिंह' से है (न कि 'बेगम हजरत महल' से)। 1857 में जगदीशपुर के 80 वर्षीय जमींदार बाबू कुँवर सिंह ने अंग्रेजों को कई बार हराया।"},
  {"q":"'1857 विद्रोह पर इतिहासकारों के मत व 1858 के परिणाम' के ऐतिहासिक संदर्भ में '1858 के प्रशासनिक बदलाव' निम्नलिखित में से क्या है?","options":["जनरल ह्यूरोज ने रानी लक्ष्मीबाई के बारे में कहा—'भारतीय क्रांतिकारियों में यहाँ सोई हुई औरत अकेली मर्द है।' प्रयागराज में लियाकत अली ने नेतृत्व किया","कार्ताज-आर्मेडा-काफिला प्रणाली (समुद्री परमिट), भारत में पहला प्रिंटिंग प्रेस (गोवा, 1556), गोथिक स्थापत्य","महारानी विक्टोरिया की 1 नवंबर 1858 घोषणा (इलाहाबाद), कंपनी शासन समाप्त कर क्राउन शासन, भारत सचिव पद, पील आयोग (सेना में यूरोपीय अनुपात बढ़ाया)","पुरानी ब्राउन बेस राइफल की जगह एनफील्ड पी-53 राइफल में गाय-सूअर की चर्बी वाले कारतूसों का प्रयोग"],"correct":2,"explanation":"बंगाल और अवध से 'मार्शल रेस' के बजाय पंजाब, गोरखा व पठान क्षेत्रों से भर्ती बढ़ाई गई और जातिगत-धार्मिक रेजिमेंट बनाकर 'फूट डालो व राज करो' अपनाया गया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1853 का चार्टर एक्ट चार्टर श्रृंखला का अंतिम अधिनियम था जिसने कंपनी के शासन की कोई निश्चित अवधि तय नहीं की।\nकथन-2: 1857 क्रांति केंद्र एवं नेता के अंतर्गत 'प्रयागराज (इलाहाबाद)' का ऐतिहासिक संबंध 'बाबू कुँवर सिंह' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (1853 का चार्टर एक्ट चार्टर श्रृंखला का अंतिम अधिनियम था जिसने कंपनी के शासन की कोई निश्चित अवधि तय नहीं की।)। कथन-2 गलत है — 'प्रयागराज (इलाहाबाद)' का सही संबंध 'मौलवी लियाकत अली' से था — इलाहाबाद में मौलवी लियाकत अली ने विद्रोह का नेतृत्व किया जिसे कर्नल नील ने क्रूरता से कुचला।"},
  {"q":"[UPSC/PCS सूची सुमेलन — 1857 क्रांति केंद्र एवं नेता] सूची-I को सूची-II से सुमेलित कीजिए:\nA. प्रयागराज (इलाहाबाद)   |   1. खान बहादुर खाँ\nB. बरेली (रुहेलखंड)   |   2. मौलवी अहमदुल्ला शाह\nC. कानपुर   |   3. मौलवी लियाकत अली\nD. फैजाबाद   |   4. नाना साहेब एवं तात्या टोपे","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: प्रयागराज (इलाहाबाद) (मौलवी लियाकत अली), बरेली (रुहेलखंड) (खान बहादुर खाँ), कानपुर (नाना साहेब एवं तात्या टोपे), फैजाबाद (मौलवी अहमदुल्ला शाह)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: बरेली में खान बहादुर खाँ ने स्वतंत्र सरकार की स्थापना कर 40,000 सैनिक जुटाए।\nकथन-2: प्रमुख आयोग एवं उद्देश्य के अंतर्गत 'हंटर शिक्षा आयोग (1882 ई.)' का ऐतिहासिक संबंध 'कलकत्ता विश्वविद्यालय की समस्याओं का अध्ययन तथा इंटरमीडिएट (10+2) परीक्षा अलग करना' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (बरेली में खान बहादुर खाँ ने स्वतंत्र सरकार की स्थापना कर 40,000 सैनिक जुटाए।)। कथन-2 गलत है — 'हंटर शिक्षा आयोग (1882 ई.)' का सही संबंध '1854 पश्चात प्राथमिक एवं माध्यमिक शिक्षा की प्रगति की समीक्षा' से था — डब्ल्यू.डब्ल्यू. हंटर की अध्यक्षता वाले आयोग ने प्राथमिक शिक्षा को स्थानीय निकायों (जिला-नगर बोर्ड) को सौंपने पर बल दिया।"},
  {"q":"'1857 के प्रमुख केंद्र, भारतीय नेतृत्व व ब्रिटिश दमनकर्ता' के ऐतिहासिक संदर्भ में 'विशेष कथन व तथ्य' निम्नलिखित में से क्या है?","options":["महारानी विक्टोरिया की 1 नवंबर 1858 घोषणा (इलाहाबाद), कंपनी शासन समाप्त कर क्राउन शासन, भारत सचिव पद, पील आयोग (सेना में यूरोपीय अनुपात बढ़ाया)","कार्ताज-आर्मेडा-काफिला प्रणाली (समुद्री परमिट), भारत में पहला प्रिंटिंग प्रेस (गोवा, 1556), गोथिक स्थापत्य","पुरानी ब्राउन बेस राइफल की जगह एनफील्ड पी-53 राइफल में गाय-सूअर की चर्बी वाले कारतूसों का प्रयोग","जनरल ह्यूरोज ने रानी लक्ष्मीबाई के बारे में कहा—'भारतीय क्रांतिकारियों में यहाँ सोई हुई औरत अकेली मर्द है।' प्रयागराज में लियाकत अली ने नेतृत्व किया"],"correct":3,"explanation":"फैजाबाद के मौलवी अहमदुल्ला शाह की गिरफ्तारी पर अंग्रेजों ने 50,000 रुपये का इनाम रखा था (रस्में जिहाद घोषित की); असम में मणिराम दीवान ने नेतृत्व किया।"},
  {"q":"[UPSC Prelims पैटर्न — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. कानपुर : नाना साहेब एवं तात्या टोपे\n2. बरेली (रुहेलखंड) : खान बहादुर खाँ\n3. जगदीशपुर (आरा) : बाबू कुँवर सिंह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (नाना साहेब (धोंधू पंत) व तात्या टोपे (रामचंद्र पांडुरंग) ने कानपुर में क्रांति का नेतृत्व किया।) युग्म 2 सही (बरेली में खान बहादुर खाँ ने स्वतंत्र सरकार की स्थापना कर 40,000 सैनिक जुटाए।) युग्म 3 सही (1857 में जगदीशपुर के 80 वर्षीय जमींदार बाबू कुँवर सिंह ने अंग्रेजों को कई बार हराया।)।"},
  {"q":"ऐतिहासिक संदर्भ में '29 मार्च 1857 बैरकपुर (34वीं NI मंगल पांडे); 10 मई मेरठ से सैनिक विद्रोह; 11-12 मई दिल्ली पर कब्जा (बहादुर शाह जफर नाममात्र नेता, बख्त खाँ वास्तविक सैन्य नेतृत्व); निकलसन व हडसन द्वारा दिल्ली दमन' (घटनाक्रम व नेता) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["1857 विद्रोह पर इतिहासकारों के मत व 1858 के परिणाम","1857 की क्रांति की शुरुआत: मंगल पांडे, मेरठ व दिल्ली","1857 के प्रमुख केंद्र, भारतीय नेतृत्व व ब्रिटिश दमनकर्ता","पुर्तगाली शक्ति का आगमन: वास्को डी गामा, अल्मीडा व अल्बुकर्क"],"correct":1,"explanation":"विद्रोह के समय शिक्षित मध्यम वर्ग, बड़े जमींदार (ज्यादातर), सिंधिया, होलकर, निजाम और पटियाला-जींद के शासकों ने अंग्रेजों का साथ दिया (कैनिंग ने इन्हें 'तूफान में तरंगअवरोध' कहा)।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. पिट्स इंडिया एक्ट, 1784 : कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण\n2. रेगुलेटिंग एक्ट, 1773 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n3. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (1784 के पिट्स इंडिया एक्ट ने पहली बार भारत में कंपनी के क्षेत्रों को 'ब्रिटिश आधिपत्य का क्षेत्र' कहा।) युग्म 2 सही (1773 के रेगुलेटिंग एक्ट से वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल बने व बंबई-मद्रास उनके अधीन हुए।) युग्म 3 सही (1919 के भारत शासन अधिनियम (मोंटफोर्ड सुधार) ने महिलाओं को मताधिकार व भारत हेतु उच्चायुक्त पद भी सृजित किया।)।"},
  {"q":"[PSC/CDS युग्म पहचान — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. प्रयागराज (इलाहाबाद) : मौलवी अहमदुल्ला शाह\n2. फैजाबाद : बेगम हजरत महल\n3. जगदीशपुर (आरा) : बाबू कुँवर सिंह\n4. लखनऊ (अवध) : नाना साहेब एवं तात्या टोपे","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: 1857 में जगदीशपुर के 80 वर्षीय जमींदार बाबू कुँवर सिंह ने अंग्रेजों को कई बार हराया। (अन्य सही युग्म: प्रयागराज (इलाहाबाद)→मौलवी लियाकत अली, फैजाबाद→मौलवी अहमदुल्ला शाह, लखनऊ (अवध)→बेगम हजरत महल)।"},
  {"q":"ऐतिहासिक संदर्भ में 'वी.डी. सावरकर ('प्रथम भारतीय स्वतंत्रता संग्राम'); आर.सी. मजूमदार ('न तो प्रथम, न राष्ट्रीय और न स्वतंत्रता संग्राम'); एस.एन. सेन ('अठारह सत्तावन' सरकारी इतिहासकार); जॉन लॉरेंस/सीले ('पूर्णतः सिपाही विद्रोह')' (इतिहासकार मत व अधिनियम) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["1857 के प्रमुख केंद्र, भारतीय नेतृत्व व ब्रिटिश दमनकर्ता","1857 की क्रांति की शुरुआत: मंगल पांडे, मेरठ व दिल्ली","पुर्तगाली शक्ति का आगमन: वास्को डी गामा, अल्मीडा व अल्बुकर्क","1857 विद्रोह पर इतिहासकारों के मत व 1858 के परिणाम"],"correct":3,"explanation":"बंगाल और अवध से 'मार्शल रेस' के बजाय पंजाब, गोरखा व पठान क्षेत्रों से भर्ती बढ़ाई गई और जातिगत-धार्मिक रेजिमेंट बनाकर 'फूट डालो व राज करो' अपनाया गया।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. चार्टर अधिनियम, 1833 : अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार\n2. भारतीय परिषद अधिनियम, 1892 : कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण\n3. पिट्स इंडिया एक्ट, 1784 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: चार्टर अधिनियम, 1833 — संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति))। युग्म 2 गलत (सही: भारतीय परिषद अधिनियम, 1892 — अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार)। युग्म 3 गलत (सही: पिट्स इंडिया एक्ट, 1784 — कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — 1857 क्रांति केंद्र एवं नेता] सूची-I को सूची-II से सुमेलित कीजिए:\nA. फैजाबाद   |   1. बेगम हजरत महल\nB. जगदीशपुर (आरा)   |   2. मौलवी अहमदुल्ला शाह\nC. लखनऊ (अवध)   |   3. खान बहादुर खाँ\nD. बरेली (रुहेलखंड)   |   4. बाबू कुँवर सिंह","options":["A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3"],"correct":0,"explanation":"सही सुमेलन: फैजाबाद (मौलवी अहमदुल्ला शाह), जगदीशपुर (आरा) (बाबू कुँवर सिंह), लखनऊ (अवध) (बेगम हजरत महल), बरेली (रुहेलखंड) (खान बहादुर खाँ)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — 1857 क्रांति केंद्र एवं नेता] सूची-I को सूची-II से सुमेलित कीजिए:\nA. बरेली (रुहेलखंड)   |   1. बेगम हजरत महल\nB. लखनऊ (अवध)   |   2. मौलवी लियाकत अली\nC. कानपुर   |   3. खान बहादुर खाँ\nD. प्रयागराज (इलाहाबाद)   |   4. नाना साहेब एवं तात्या टोपे","options":["A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2"],"correct":1,"explanation":"सही सुमेलन: बरेली (रुहेलखंड) (खान बहादुर खाँ), लखनऊ (अवध) (बेगम हजरत महल), कानपुर (नाना साहेब एवं तात्या टोपे), प्रयागराज (इलाहाबाद) (मौलवी लियाकत अली)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. जगदीशपुर (आरा) : बाबू कुँवर सिंह\n2. लखनऊ (अवध) : मौलवी लियाकत अली\n3. फैजाबाद : मौलवी अहमदुल्ला शाह\n4. बरेली (रुहेलखंड) : खान बहादुर खाँ","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'लखनऊ (अवध)' का सही संबंध 'बेगम हजरत महल' से है (न कि 'मौलवी लियाकत अली' से)। बेगम हजरत महल ने 1857 में लखनऊ में विद्रोह की कमान संभाली तथा अंततः नेपाल पलायन किया।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. चार्टर अधिनियम, 1813 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\n2. पिट्स इंडिया एक्ट, 1784 : कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण\n3. रेगुलेटिंग एक्ट, 1773 : अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार\n4. भारत शासन अधिनियम, 1858 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'रेगुलेटिंग एक्ट, 1773' का सही संबंध 'गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ' से है (न कि 'अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार' से)। 1773 के रेगुलेटिंग एक्ट से वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल बने व बंबई-मद्रास उनके अधीन हुए।"},
  {"q":"1857 में फैजाबाद में किस क्रांतिकारी मौलवी ने अंग्रेजों के विरुद्ध 'जिहाद' का आह्वान किया?","options":["मौलवी अहमदुल्ला शाह","बाबू कुँवर सिंह","बेगम हजरत महल","नाना साहेब एवं तात्या टोपे"],"correct":0,"explanation":"मौलवी अहमदुल्ला 1857 के सबसे कट्टर ब्रिटिश-विरोधी नेता थे जिन पर 50,000 रु. का इनाम था। अंग्रेजों ने उन्हें 'सर्वोत्तम सैनिक और सबसे दुर्जेय शत्रु' स्वीकार किया।"},
  {"q":"[UPSC/PCS सूची सुमेलन — 1857 क्रांति केंद्र एवं नेता] सूची-I को सूची-II से सुमेलित कीजिए:\nA. कानपुर   |   1. मौलवी लियाकत अली\nB. बरेली (रुहेलखंड)   |   2. मौलवी अहमदुल्ला शाह\nC. फैजाबाद   |   3. नाना साहेब एवं तात्या टोपे\nD. प्रयागराज (इलाहाबाद)   |   4. खान बहादुर खाँ","options":["A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1"],"correct":3,"explanation":"सही सुमेलन: कानपुर (नाना साहेब एवं तात्या टोपे), बरेली (रुहेलखंड) (खान बहादुर खाँ), फैजाबाद (मौलवी अहमदुल्ला शाह), प्रयागराज (इलाहाबाद) (मौलवी लियाकत अली)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. आर्य समाज (1875)   B. रेगुलेटिंग एक्ट, 1773\nC. आंग्ल-मराठा व आंग्ल-सिख युद्ध तथा प्रमुख संधियाँ   D. 19वीं सदी के प्रमुख महिला सुधारक: सावित्रीबाई, पंडिता रमाबाई व ताराबाई शिंदे\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["रेगुलेटिंग एक्ट, 1773","आंग्ल-मराठा व आंग्ल-सिख युद्ध तथा प्रमुख संधियाँ","19वीं सदी के प्रमुख महिला सुधारक: सावित्रीबाई, पंडिता रमाबाई व ताराबाई शिंदे","आर्य समाज (1875)"],"correct":0,"explanation":"रेगुलेटिंग एक्ट, 1773 (1773 ई.), आंग्ल-मराठा व आंग्ल-सिख युद्ध तथा प्रमुख संधियाँ (1818 ई.), आर्य समाज (1875) (1875 ई.), 19वीं सदी के प्रमुख महिला सुधारक: सावित्रीबाई, पंडिता रमाबाई व ताराबाई शिंदे (1882 ई.)। अतः सर्वप्रथम रेगुलेटिंग एक्ट, 1773।"},
  {"q":"1857 के प्रमुख केंद्र, भारतीय नेतृत्व व ब्रिटिश दमनकर्ता — इसके संबंध में 'केंद्र व नेता युग्म' कौन/क्या था?","options":["वी.डी. सावरकर ('प्रथम भारतीय स्वतंत्रता संग्राम'); आर.सी. मजूमदार ('न तो प्रथम, न राष्ट्रीय और न स्वतंत्रता संग्राम'); एस.एन. सेन ('अठारह सत्तावन' सरकारी इतिहासकार); जॉन लॉरेंस/सीले ('पूर्णतः सिपाही विद्रोह')","वास्को डी गामा (1498 कालीकट, जमोरिन द्वारा स्वागत); फ्रांसिस्को डी अल्मीडा ('ब्लू वाटर पॉलिसी'); अल्बुकर्क (वास्तविक संस्थापक, 1510 में बीजापुर से गोवा छीना, सती प्रथा पर रोक)","कानपुर (नाना साहेब व तात्या टोपे — कॉलिन कैम्पबेल दमन); लखनऊ (बेगम हजरत महल — कैम्पबेल); झाँसी/ग्वालियर (रानी लक्ष्मीबाई — ह्यूरोज); जगदीशपुर/आरा (बाबू कुँवर सिंह — विलियम टेलर); फैजाबाद (मौलवी अहमदुल्ला); बरेली (खान बहादुर)","29 मार्च 1857 बैरकपुर (34वीं NI मंगल पांडे); 10 मई मेरठ से सैनिक विद्रोह; 11-12 मई दिल्ली पर कब्जा (बहादुर शाह जफर नाममात्र नेता, बख्त खाँ वास्तविक सैन्य नेतृत्व); निकलसन व हडसन द्वारा दिल्ली दमन"],"correct":2,"explanation":"फैजाबाद के मौलवी अहमदुल्ला शाह की गिरफ्तारी पर अंग्रेजों ने 50,000 रुपये का इनाम रखा था (रस्में जिहाद घोषित की); असम में मणिराम दीवान ने नेतृत्व किया।"},
  {"q":"[UPSC Prelims पैटर्न — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बरेली (रुहेलखंड) : खान बहादुर खाँ\n2. लखनऊ (अवध) : बेगम हजरत महल\n3. जगदीशपुर (आरा) : नाना साहेब एवं तात्या टोपे\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (बरेली में खान बहादुर खाँ ने स्वतंत्र सरकार की स्थापना कर 40,000 सैनिक जुटाए।) युग्म 2 सही (बेगम हजरत महल ने 1857 में लखनऊ में विद्रोह की कमान संभाली तथा अंततः नेपाल पलायन किया।) युग्म 3 गलत (सही: जगदीशपुर (आरा) — बाबू कुँवर सिंह)।"},
  {"q":"[UPSC Prelims पैटर्न — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. फैजाबाद : मौलवी अहमदुल्ला शाह\n2. बरेली (रुहेलखंड) : बाबू कुँवर सिंह\n3. जगदीशपुर (आरा) : बेगम हजरत महल\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (मौलवी अहमदुल्ला 1857 के सबसे कट्टर ब्रिटिश-विरोधी नेता थे जिन पर 50,000 रु. का इनाम था।) युग्म 2 गलत (सही: बरेली (रुहेलखंड) — खान बहादुर खाँ)। युग्म 3 गलत (सही: जगदीशपुर (आरा) — बाबू कुँवर सिंह)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. पिट्स इंडिया एक्ट, 1784 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\n2. भारत शासन अधिनियम, 1935 : अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण\n3. चार्टर अधिनियम, 1853 : केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता\n4. चार्टर अधिनियम, 1813 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'पिट्स इंडिया एक्ट, 1784' का सही संबंध 'कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण' से है (न कि 'मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)' से)। 1784 के पिट्स इंडिया एक्ट ने पहली बार भारत में कंपनी के क्षेत्रों को 'ब्रिटिश आधिपत्य का क्षेत्र' कहा।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. पिट्स इंडिया एक्ट, 1784 : कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण\n2. रेगुलेटिंग एक्ट, 1773 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n3. भारतीय परिषद अधिनियम, 1861 : केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (1784 के पिट्स इंडिया एक्ट ने पहली बार भारत में कंपनी के क्षेत्रों को 'ब्रिटिश आधिपत्य का क्षेत्र' कहा।) युग्म 2 सही (1773 के रेगुलेटिंग एक्ट से वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल बने व बंबई-मद्रास उनके अधीन हुए।) युग्म 3 गलत (सही: भारतीय परिषद अधिनियम, 1861 — मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1857 क्रांति केंद्र एवं नेता के अंतर्गत 'जगदीशपुर (आरा)' का ऐतिहासिक संबंध 'बेगम हजरत महल' से था।\nकथन-2: सुधार संगठन एवं संस्थापक के अंतर्गत 'आर्य समाज (1875)' का ऐतिहासिक संबंध 'ज्योतिबा फुले' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'जगदीशपुर (आरा)' का सही संबंध 'बाबू कुँवर सिंह' से था — 1857 में जगदीशपुर के 80 वर्षीय जमींदार बाबू कुँवर सिंह ने अंग्रेजों को कई बार हराया। (2) 'आर्य समाज (1875)' का सही संबंध 'स्वामी दयानंद सरस्वती' से था — स्वामी दयानंद सरस्वती (मूलशंकर) ने वेदों की ओर लौटने के आह्वान सहित आर्य समाज स्थापित किया।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. कानपुर : नाना साहेब एवं तात्या टोपे\n2. फैजाबाद : मौलवी लियाकत अली\n3. जगदीशपुर (आरा) : बाबू कुँवर सिंह\n4. बरेली (रुहेलखंड) : खान बहादुर खाँ","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'फैजाबाद' का सही संबंध 'मौलवी अहमदुल्ला शाह' से है (न कि 'मौलवी लियाकत अली' से)। मौलवी अहमदुल्ला 1857 के सबसे कट्टर ब्रिटिश-विरोधी नेता थे जिन पर 50,000 रु. का इनाम था।"},
  {"q":"[PSC/CDS युग्म पहचान — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. बरेली (रुहेलखंड) : मौलवी अहमदुल्ला शाह\n2. फैजाबाद : बेगम हजरत महल\n3. लखनऊ (अवध) : नाना साहेब एवं तात्या टोपे\n4. प्रयागराज (इलाहाबाद) : मौलवी लियाकत अली","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: इलाहाबाद में मौलवी लियाकत अली ने विद्रोह का नेतृत्व किया जिसे कर्नल नील ने क्रूरता से कुचला। (अन्य सही युग्म: बरेली (रुहेलखंड)→खान बहादुर खाँ, फैजाबाद→मौलवी अहमदुल्ला शाह, लखनऊ (अवध)→बेगम हजरत महल)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. जगदीशपुर (आरा) : बाबू कुँवर सिंह\n2. फैजाबाद : मौलवी अहमदुल्ला शाह\n3. लखनऊ (अवध) : बेगम हजरत महल\n4. कानपुर : मौलवी लियाकत अली","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'कानपुर' का सही संबंध 'नाना साहेब एवं तात्या टोपे' से है (न कि 'मौलवी लियाकत अली' से)। नाना साहेब (धोंधू पंत) व तात्या टोपे (रामचंद्र पांडुरंग) ने कानपुर में क्रांति का नेतृत्व किया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1857 के बाद गठित पील आयोग (Peel Commission) ने बंगाल सेना में भारतीय सैनिकों का अनुपात बढ़ाकर 10:1 करने की सिफारिश की थी।\nकथन-2: व्यपगत सिद्धांत (विलय वर्ष) के अंतर्गत 'नागपुर विलय' का ऐतिहासिक संबंध '1848 ई. (प्रथम व्यपगत राज्य)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) पील आयोग की सिफारिश पर बंगाल सेना में यूरोपीय व भारतीय सैनिकों का अनुपात 1:2 तथा मद्रास-बंबई में 1:3 कर दिया गया, एवं तोपखाना केवल यूरोपीय हाथों में रहा। (2) 'नागपुर विलय' का सही संबंध '1854 ई.' से था — रघुजी तृतीय के निधन के बाद 1854 ई. में नागपुर का ब्रिटिश साम्राज्य में विलय हो गया।"},
  {"q":"[PSC/CDS युग्म पहचान — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद\n2. चार्टर अधिनियम, 1833 : संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\n3. भारत शासन अधिनियम, 1858 : केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता\n4. चार्टर अधिनियम, 1853 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: 1833 के चार्टर एक्ट से लॉर्ड विलियम बेंटिंक भारत के प्रथम गवर्नर-जनरल बने। (अन्य सही युग्म: भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)→प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली, भारत शासन अधिनियम, 1858→कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद, चार्टर अधिनियम, 1853→केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: बरेली में खान बहादुर खाँ ने स्वतंत्र सरकार की स्थापना कर 40,000 सैनिक जुटाए।\nकथन-2: प्रमुख संधियाँ एवं समझौते के अंतर्गत 'यांडबू की संधि (1826 ई.)' का ऐतिहासिक संबंध 'महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (बरेली में खान बहादुर खाँ ने स्वतंत्र सरकार की स्थापना कर 40,000 सैनिक जुटाए।)। कथन-2 गलत है — 'यांडबू की संधि (1826 ई.)' का सही संबंध 'प्रथम आंग्ल-बर्मा युद्ध का अंत (असम, मणिपुर व अराकान-तेनासेरिम से बर्मा का दावा समाप्त)' से था — लॉर्ड एमहर्स्ट के शासन में 1824-26 का प्रथम आंग्ल-बर्मा युद्ध 1826 की यांडबू संधि से समाप्त हुआ।"},
  {"q":"1857 की क्रांति की शुरुआत: मंगल पांडे, मेरठ व दिल्ली — इसके संबंध में 'घटनाक्रम व नेता' कौन/क्या था?","options":["वी.डी. सावरकर ('प्रथम भारतीय स्वतंत्रता संग्राम'); आर.सी. मजूमदार ('न तो प्रथम, न राष्ट्रीय और न स्वतंत्रता संग्राम'); एस.एन. सेन ('अठारह सत्तावन' सरकारी इतिहासकार); जॉन लॉरेंस/सीले ('पूर्णतः सिपाही विद्रोह')","कानपुर (नाना साहेब व तात्या टोपे — कॉलिन कैम्पबेल दमन); लखनऊ (बेगम हजरत महल — कैम्पबेल); झाँसी/ग्वालियर (रानी लक्ष्मीबाई — ह्यूरोज); जगदीशपुर/आरा (बाबू कुँवर सिंह — विलियम टेलर); फैजाबाद (मौलवी अहमदुल्ला); बरेली (खान बहादुर)","29 मार्च 1857 बैरकपुर (34वीं NI मंगल पांडे); 10 मई मेरठ से सैनिक विद्रोह; 11-12 मई दिल्ली पर कब्जा (बहादुर शाह जफर नाममात्र नेता, बख्त खाँ वास्तविक सैन्य नेतृत्व); निकलसन व हडसन द्वारा दिल्ली दमन","वास्को डी गामा (1498 कालीकट, जमोरिन द्वारा स्वागत); फ्रांसिस्को डी अल्मीडा ('ब्लू वाटर पॉलिसी'); अल्बुकर्क (वास्तविक संस्थापक, 1510 में बीजापुर से गोवा छीना, सती प्रथा पर रोक)"],"correct":2,"explanation":"विद्रोह के समय शिक्षित मध्यम वर्ग, बड़े जमींदार (ज्यादातर), सिंधिया, होलकर, निजाम और पटियाला-जींद के शासकों ने अंग्रेजों का साथ दिया (कैनिंग ने इन्हें 'तूफान में तरंगअवरोध' कहा)।"},
  {"q":"बंगाल में 1772 में 'द्वैध शासन' समाप्त करने और प्रत्येक जिले में फौजदारी-दीवानी अदालतें बनाने वाले गवर्नर कौन थे?","options":["1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना","बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना","द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त","सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)"],"correct":2,"explanation":"वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल (1773 एक्ट) बने; उन्होंने कलकत्ता मदरसा (1781) की स्थापना भी की। इंग्लैंड लौटने पर एडमंड बर्क आदि ने इन पर महाभियोग चलाया जिससे वे बाद में बरी हुए।"},
  {"q":"1857 विद्रोह पर इतिहासकारों के मत व 1858 के परिणाम — इसके संबंध में 'इतिहासकार मत व अधिनियम' कौन/क्या था?","options":["वी.डी. सावरकर ('प्रथम भारतीय स्वतंत्रता संग्राम'); आर.सी. मजूमदार ('न तो प्रथम, न राष्ट्रीय और न स्वतंत्रता संग्राम'); एस.एन. सेन ('अठारह सत्तावन' सरकारी इतिहासकार); जॉन लॉरेंस/सीले ('पूर्णतः सिपाही विद्रोह')","वास्को डी गामा (1498 कालीकट, जमोरिन द्वारा स्वागत); फ्रांसिस्को डी अल्मीडा ('ब्लू वाटर पॉलिसी'); अल्बुकर्क (वास्तविक संस्थापक, 1510 में बीजापुर से गोवा छीना, सती प्रथा पर रोक)","कानपुर (नाना साहेब व तात्या टोपे — कॉलिन कैम्पबेल दमन); लखनऊ (बेगम हजरत महल — कैम्पबेल); झाँसी/ग्वालियर (रानी लक्ष्मीबाई — ह्यूरोज); जगदीशपुर/आरा (बाबू कुँवर सिंह — विलियम टेलर); फैजाबाद (मौलवी अहमदुल्ला); बरेली (खान बहादुर)","29 मार्च 1857 बैरकपुर (34वीं NI मंगल पांडे); 10 मई मेरठ से सैनिक विद्रोह; 11-12 मई दिल्ली पर कब्जा (बहादुर शाह जफर नाममात्र नेता, बख्त खाँ वास्तविक सैन्य नेतृत्व); निकलसन व हडसन द्वारा दिल्ली दमन"],"correct":0,"explanation":"बंगाल और अवध से 'मार्शल रेस' के बजाय पंजाब, गोरखा व पठान क्षेत्रों से भर्ती बढ़ाई गई और जातिगत-धार्मिक रेजिमेंट बनाकर 'फूट डालो व राज करो' अपनाया गया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. झाँसी विलय (गंगाधर राव मृत्यु बाद)   B. जैतपुर व संबलपुर विलय\nC. भारत में प्रेस का विकास, प्रमुख पत्र-पत्रिकाएँ व दमनकारी एक्ट   D. पिट्स इंडिया एक्ट, 1784\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["झाँसी विलय (गंगाधर राव मृत्यु बाद)","जैतपुर व संबलपुर विलय","पिट्स इंडिया एक्ट, 1784","भारत में प्रेस का विकास, प्रमुख पत्र-पत्रिकाएँ व दमनकारी एक्ट"],"correct":2,"explanation":"पिट्स इंडिया एक्ट, 1784 (1784 ई.), जैतपुर व संबलपुर विलय (1849 ई.), झाँसी विलय (गंगाधर राव मृत्यु बाद) (1853 ई.), भारत में प्रेस का विकास, प्रमुख पत्र-पत्रिकाएँ व दमनकारी एक्ट (1878 ई.)। अतः सर्वप्रथम पिट्स इंडिया एक्ट, 1784।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. फैजाबाद : मौलवी अहमदुल्ला शाह\n2. प्रयागराज (इलाहाबाद) : नाना साहेब एवं तात्या टोपे\n3. बरेली (रुहेलखंड) : खान बहादुर खाँ\n4. जगदीशपुर (आरा) : बाबू कुँवर सिंह","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'प्रयागराज (इलाहाबाद)' का सही संबंध 'मौलवी लियाकत अली' से है (न कि 'नाना साहेब एवं तात्या टोपे' से)। इलाहाबाद में मौलवी लियाकत अली ने विद्रोह का नेतृत्व किया जिसे कर्नल नील ने क्रूरता से कुचला।"},
  {"q":"1857 के विद्रोह में कानपुर का नेतृत्व नाना साहेब के साथ किस महान सेनापति ने किया?","options":["बेगम हजरत महल","बाबू कुँवर सिंह","मौलवी अहमदुल्ला शाह","नाना साहेब एवं तात्या टोपे"],"correct":3,"explanation":"नाना साहेब (धोंधू पंत) व तात्या टोपे (रामचंद्र पांडुरंग) ने कानपुर में क्रांति का नेतृत्व किया। तात्या टोपे 1859 में नरवर के मानसिंह के विश्वासघात से पकड़े गए।"},
  {"q":"[UPSC/PCS सूची सुमेलन — संवैधानिक अधिनियम एवं प्रावधान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. चार्टर अधिनियम, 1833   |   1. अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार\nB. चार्टर अधिनियम, 1853   |   2. संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\nC. भारतीय परिषद अधिनियम, 1892   |   3. मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\nD. भारतीय परिषद अधिनियम, 1861   |   4. केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता","options":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1"],"correct":0,"explanation":"सही सुमेलन: चार्टर अधिनियम, 1833 (संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)), चार्टर अधिनियम, 1853 (केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता), भारतीय परिषद अधिनियम, 1892 (अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार), भारतीय परिषद अधिनियम, 1861 (मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह))।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. चार्टर अधिनियम, 1853   B. 1857 की क्रांति की शुरुआत: मंगल पांडे, मेरठ व दिल्ली\nC. वुड्स डिस्पैच (1854 ई.)   D. संन्यासी विद्रोह, पाइक विद्रोह, कोल विद्रोह एवं संथाल हूल (1855-56)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["वुड्स डिस्पैच (1854 ई.)","संन्यासी विद्रोह, पाइक विद्रोह, कोल विद्रोह एवं संथाल हूल (1855-56)","1857 की क्रांति की शुरुआत: मंगल पांडे, मेरठ व दिल्ली","चार्टर अधिनियम, 1853"],"correct":2,"explanation":"चार्टर अधिनियम, 1853 (1853 ई.), वुड्स डिस्पैच (1854 ई.) (1854 ई.), संन्यासी विद्रोह, पाइक विद्रोह, कोल विद्रोह एवं संथाल हूल (1855-56) (1855-56 ई.), 1857 की क्रांति की शुरुआत: मंगल पांडे, मेरठ व दिल्ली (1857 ई.)। अतः सबसे अंत में 1857 की क्रांति की शुरुआत: मंगल पांडे, मेरठ व दिल्ली।"},
  {"q":"[PSC/CDS युग्म पहचान — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. लखनऊ (अवध) : मौलवी लियाकत अली\n2. फैजाबाद : मौलवी अहमदुल्ला शाह\n3. प्रयागराज (इलाहाबाद) : नाना साहेब एवं तात्या टोपे\n4. कानपुर : खान बहादुर खाँ","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: मौलवी अहमदुल्ला 1857 के सबसे कट्टर ब्रिटिश-विरोधी नेता थे जिन पर 50,000 रु. का इनाम था। (अन्य सही युग्म: लखनऊ (अवध)→बेगम हजरत महल, प्रयागराज (इलाहाबाद)→मौलवी लियाकत अली, कानपुर→नाना साहेब एवं तात्या टोपे)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1833 के चार्टर एक्ट से लॉर्ड विलियम बेंटिंक भारत के प्रथम गवर्नर-जनरल बने।\nकथन-2: 1857 में लखनऊ विद्रोह का नेतृत्व कुँवर सिंह ने किया और कानपुर में विद्रोह को जनरल ह्यूरोज ने दबाया था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (1833 के चार्टर एक्ट से लॉर्ड विलियम बेंटिंक भारत के प्रथम गवर्नर-जनरल बने।)। कथन-2 गलत है — लखनऊ (अवध) का नेतृत्व बेगम हजरत महल ने किया, कानपुर का नाना साहेब व तात्या टोपे ने (दमन: कैंपबेल), और बाबू कुँवर सिंह जगदीशपुर (बिहार) के नायक थे।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: गवर्नर-जनरल / वायसराय एवं कार्य के अंतर्गत 'वॉरेन हेस्टिंग्स (1772-85)' का ऐतिहासिक संबंध 'बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना' से था।\nकथन-2: 1853 का चार्टर एक्ट चार्टर श्रृंखला का अंतिम अधिनियम था जिसने कंपनी के शासन की कोई निश्चित अवधि तय नहीं की।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('वॉरेन हेस्टिंग्स (1772-85)' का सही संबंध 'द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त' से था — वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल (1773 एक्ट) बने; उन्होंने कलकत्ता मदरसा (1781) की स्थापना भी की।)। कथन-2 सत्य है (1853 का चार्टर एक्ट चार्टर श्रृंखला का अंतिम अधिनियम था जिसने कंपनी के शासन की कोई निश्चित अवधि तय नहीं की।)।"},
  {"q":"[PSC/CDS युग्म पहचान — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. भारत शासन अधिनियम, 1935 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद\n2. भारत शासन अधिनियम, 1858 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\n3. रेगुलेटिंग एक्ट, 1773 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n4. चार्टर अधिनियम, 1813 : कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: 1773 के रेगुलेटिंग एक्ट से वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल बने व बंबई-मद्रास उनके अधीन हुए। (अन्य सही युग्म: भारत शासन अधिनियम, 1935→अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण, भारत शासन अधिनियम, 1858→कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद, चार्टर अधिनियम, 1813→भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. इलाहाबाद की संधियाँ (1765 ई.)   B. बंगाल गजट (1780)\nC. एक्स-ला-शैपल की संधि (1748 ई.)   D. फैजाबाद\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["इलाहाबाद की संधियाँ (1765 ई.)","एक्स-ला-शैपल की संधि (1748 ई.)","बंगाल गजट (1780)","फैजाबाद"],"correct":3,"explanation":"एक्स-ला-शैपल की संधि (1748 ई.) (1748 ई.), इलाहाबाद की संधियाँ (1765 ई.) (1765 ई.), बंगाल गजट (1780) (1780 ई.), फैजाबाद (1857 ई.)। अतः सबसे अंत में फैजाबाद।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1857 क्रांति केंद्र एवं नेता के अंतर्गत 'फैजाबाद' का ऐतिहासिक संबंध 'खान बहादुर खाँ' से था।\nकथन-2: भारत में रेल निर्माण के लिए ब्रिटिश निजी कंपनियों को सरकारी गारंटी पर 0% ब्याज और संपूर्ण पूंजी केवल भारतीय किसानों के स्वैच्छिक शेयर से जुटाई गई थी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'फैजाबाद' का सही संबंध 'मौलवी अहमदुल्ला शाह' से था — मौलवी अहमदुल्ला 1857 के सबसे कट्टर ब्रिटिश-विरोधी नेता थे जिन पर 50,000 रु. का इनाम था। (2) भारतीय रेलवे का निर्माण 'गारंटीड इंटरेस्ट सिस्टम' (ब्रिटिश निवेशकों को भारतीय करदाताओं के धन से 5% सुनिश्चित न्यूनतम लाभ की गारंटी) पर हुआ था।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. रेगुलेटिंग एक्ट, 1773 : अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण\n2. भारत शासन अधिनियम, 1935 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\n3. चार्टर अधिनियम, 1813 : केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: रेगुलेटिंग एक्ट, 1773 — गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ)। युग्म 2 गलत (सही: भारत शासन अधिनियम, 1935 — अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण)। युग्म 3 गलत (सही: चार्टर अधिनियम, 1813 — भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष)।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. चार्टर अधिनियम, 1813 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\n2. भारतीय परिषद अधिनियम, 1892 : संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\n3. चार्टर अधिनियम, 1833 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (1813 के चार्टर एक्ट से यूरोपीय व्यापारियों व ईसाई मिशनरियों को भारत आने की अनुमति मिली।) युग्म 2 गलत (सही: भारतीय परिषद अधिनियम, 1892 — अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार)। युग्म 3 गलत (सही: चार्टर अधिनियम, 1833 — संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति))।"},
  {"q":"[UPSC Prelims पैटर्न — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. फैजाबाद : मौलवी अहमदुल्ला शाह\n2. बरेली (रुहेलखंड) : बाबू कुँवर सिंह\n3. जगदीशपुर (आरा) : मौलवी लियाकत अली\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (मौलवी अहमदुल्ला 1857 के सबसे कट्टर ब्रिटिश-विरोधी नेता थे जिन पर 50,000 रु. का इनाम था।) युग्म 2 गलत (सही: बरेली (रुहेलखंड) — खान बहादुर खाँ)। युग्म 3 गलत (सही: जगदीशपुर (आरा) — बाबू कुँवर सिंह)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. भारत शासन अधिनियम, 1858 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद\n2. भारतीय परिषद अधिनियम, 1861 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\n3. चार्टर अधिनियम, 1813 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n4. भारत शासन अधिनियम, 1935 : अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'चार्टर अधिनियम, 1813' का सही संबंध 'भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष' से है (न कि 'गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ' से)। 1813 के चार्टर एक्ट से यूरोपीय व्यापारियों व ईसाई मिशनरियों को भारत आने की अनुमति मिली।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. आधुनिक शिक्षा का विकास: मैकाले से सार्जेंट योजना तक   B. फैजाबाद\nC. लॉर्ड डलहौजी (1848-56)   D. उदंत मार्तंड (1826, प्रथम हिंदी पत्र)\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["आधुनिक शिक्षा का विकास: मैकाले से सार्जेंट योजना तक","फैजाबाद","उदंत मार्तंड (1826, प्रथम हिंदी पत्र)","लॉर्ड डलहौजी (1848-56)"],"correct":1,"explanation":"उदंत मार्तंड (1826, प्रथम हिंदी पत्र) (1826 ई.), लॉर्ड डलहौजी (1848-56) (1853 ई.), आधुनिक शिक्षा का विकास: मैकाले से सार्जेंट योजना तक (1854 ई.), फैजाबाद (1857 ई.)। अतः सबसे अंत में फैजाबाद।"},
  {"q":"किस चार्टर अधिनियम ने विधायी एवं कार्यकारी कार्यों को पृथक किया तथा भारतीय सिविल सेवा हेतु खुली प्रतियोगिता (मैकाल समिति) प्रारंभ की?","options":["कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ","केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता","भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष"],"correct":2,"explanation":"1853 का चार्टर एक्ट चार्टर श्रृंखला का अंतिम अधिनियम था जिसने कंपनी के शासन की कोई निश्चित अवधि तय नहीं की। मैकाले समिति (1854) की अनुशंसा पर प्रतियोगी परीक्षा के आधार पर ICS भर्ती शुरू हुई।"},
  {"q":"[UPSC Prelims पैटर्न — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. प्रयागराज (इलाहाबाद) : मौलवी लियाकत अली\n2. जगदीशपुर (आरा) : बाबू कुँवर सिंह\n3. लखनऊ (अवध) : मौलवी अहमदुल्ला शाह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (इलाहाबाद में मौलवी लियाकत अली ने विद्रोह का नेतृत्व किया जिसे कर्नल नील ने क्रूरता से कुचला।) युग्म 2 सही (1857 में जगदीशपुर के 80 वर्षीय जमींदार बाबू कुँवर सिंह ने अंग्रेजों को कई बार हराया।) युग्म 3 गलत (सही: लखनऊ (अवध) — बेगम हजरत महल)।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. वॉरेन हेस्टिंग्स (1772-85) : 1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम\n2. लॉर्ड कैनिंग (1856-62) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन\n3. लॉर्ड कर्जन (1899-1905) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: वॉरेन हेस्टिंग्स (1772-85) — द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त)। युग्म 2 गलत (सही: लॉर्ड कैनिंग (1856-62) — 1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम)। युग्म 3 गलत (सही: लॉर्ड कर्जन (1899-1905) — बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन)।"},
  {"q":"किस चार्टर अधिनियम द्वारा कंपनी के वाणिज्यिक कार्य पूर्णतः समाप्त कर बंगाल के गवर्नर-जनरल को 'भारत का गवर्नर-जनरल' बनाया गया?","options":["संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)","कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष","गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ"],"correct":0,"explanation":"1833 के चार्टर एक्ट से लॉर्ड विलियम बेंटिंक भारत के प्रथम गवर्नर-जनरल बने। इसकी धारा 87 में योग्यता के आधार पर सरकारी सेवा में जाति-धर्म-वर्ण भेदभाव न करने की बात थी।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. चार्टर अधिनियम, 1813 : संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\n2. चार्टर अधिनियम, 1833 : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\n3. भारतीय परिषद अधिनियम, 1909 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: चार्टर अधिनियम, 1813 — भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष)। युग्म 2 गलत (सही: चार्टर अधिनियम, 1833 — संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति))। युग्म 3 गलत (सही: भारतीय परिषद अधिनियम, 1909 — मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: संवैधानिक अधिनियम एवं प्रावधान के अंतर्गत 'चार्टर अधिनियम, 1813' का ऐतिहासिक संबंध 'संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)' से था।\nकथन-2: पत्र-पत्रिकाएँ एवं संपादक के अंतर्गत 'द बंगाली (The Bengalee)' का ऐतिहासिक संबंध 'जेम्स ऑगस्टस हिक्की' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'चार्टर अधिनियम, 1813' का सही संबंध 'भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष' से था — 1813 के चार्टर एक्ट से यूरोपीय व्यापारियों व ईसाई मिशनरियों को भारत आने की अनुमति मिली। (2) 'द बंगाली (The Bengalee)' का सही संबंध 'सुरेंद्रनाथ बनर्जी' से था — सुरेंद्रनाथ बनर्जी ने 1879 से 'द बंगाली' का संपादन कर सिविल सेवा व संवैधानिक सुधारों की आवाज उठाई।"},
  {"q":"[PSC/CDS युग्म पहचान — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. चार्टर अधिनियम, 1813 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\n2. भारतीय परिषद अधिनियम, 1861 : अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार\n3. भारतीय परिषद अधिनियम, 1892 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n4. रेगुलेटिंग एक्ट, 1773 : अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: 1813 के चार्टर एक्ट से यूरोपीय व्यापारियों व ईसाई मिशनरियों को भारत आने की अनुमति मिली। (अन्य सही युग्म: भारतीय परिषद अधिनियम, 1861→मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह), भारतीय परिषद अधिनियम, 1892→अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार, रेगुलेटिंग एक्ट, 1773→गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — संवैधानिक अधिनियम एवं प्रावधान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. पिट्स इंडिया एक्ट, 1784   |   1. मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\nB. भारतीय परिषद अधिनियम, 1861   |   2. अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण\nC. चार्टर अधिनियम, 1833   |   3. कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण\nD. भारत शासन अधिनियम, 1935   |   4. संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)","options":["A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: पिट्स इंडिया एक्ट, 1784 (कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण), भारतीय परिषद अधिनियम, 1861 (मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)), चार्टर अधिनियम, 1833 (संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)), भारत शासन अधिनियम, 1935 (अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण)।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. रेगुलेटिंग एक्ट, 1773 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n2. भारत शासन अधिनियम, 1935 : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\n3. भारतीय परिषद अधिनियम, 1909 : कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (1773 के रेगुलेटिंग एक्ट से वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल बने व बंबई-मद्रास उनके अधीन हुए।) युग्म 2 गलत (सही: भारत शासन अधिनियम, 1935 — अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण)। युग्म 3 गलत (सही: भारतीय परिषद अधिनियम, 1909 — मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य)।"},
  {"q":"[UPSC Prelims पैटर्न — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बरेली (रुहेलखंड) : बाबू कुँवर सिंह\n2. जगदीशपुर (आरा) : मौलवी अहमदुल्ला शाह\n3. फैजाबाद : बेगम हजरत महल\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: बरेली (रुहेलखंड) — खान बहादुर खाँ)। युग्म 2 गलत (सही: जगदीशपुर (आरा) — बाबू कुँवर सिंह)। युग्म 3 गलत (सही: फैजाबाद — मौलवी अहमदुल्ला शाह)।"},
  {"q":"बंगाल के प्रथम गवर्नर-जनरल कौन थे जिन्होंने 'सुरक्षा प्रकोष्ठ' (Ring-Fence) नीति चलाई?","options":["लॉर्ड विलियम बेंटिंक (1828-35)","चार्ल्स मेटकाफ (1835-36)","वॉरेन हेस्टिंग्स (1772-85)","लॉर्ड कॉर्नवालिस (1786-93)"],"correct":2,"explanation":"वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल (1773 एक्ट) बने; उन्होंने कलकत्ता मदरसा (1781) की स्थापना भी की। इंग्लैंड लौटने पर एडमंड बर्क आदि ने इन पर महाभियोग चलाया जिससे वे बाद में बरी हुए।"},
  {"q":"[UPSC/PCS सूची सुमेलन — संवैधानिक अधिनियम एवं प्रावधान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. पिट्स इंडिया एक्ट, 1784   |   1. संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\nB. चार्टर अधिनियम, 1833   |   2. गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\nC. भारतीय परिषद अधिनियम, 1909   |   3. कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण\nD. रेगुलेटिंग एक्ट, 1773   |   4. मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: पिट्स इंडिया एक्ट, 1784 (कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण), चार्टर अधिनियम, 1833 (संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)), भारतीय परिषद अधिनियम, 1909 (मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य), रेगुलेटिंग एक्ट, 1773 (गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ)।"},
  {"q":"1857 के विद्रोह में बरेली (रुहेलखंड) में क्रांतिकारियों का नेतृत्व किसने संभाला?","options":["बेगम हजरत महल","नाना साहेब एवं तात्या टोपे","खान बहादुर खाँ","बाबू कुँवर सिंह"],"correct":2,"explanation":"बरेली में खान बहादुर खाँ ने स्वतंत्र सरकार की स्थापना कर 40,000 सैनिक जुटाए। उनके साथ बख्त खाँ ने दिल्ली के मोर्चे का सैन्य संचालन संभाला।"},
  {"q":"[PSC/CDS युग्म पहचान — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. बरेली (रुहेलखंड) : मौलवी लियाकत अली\n2. प्रयागराज (इलाहाबाद) : मौलवी अहमदुल्ला शाह\n3. फैजाबाद : नाना साहेब एवं तात्या टोपे\n4. लखनऊ (अवध) : बेगम हजरत महल","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: बेगम हजरत महल ने 1857 में लखनऊ में विद्रोह की कमान संभाली तथा अंततः नेपाल पलायन किया। (अन्य सही युग्म: बरेली (रुहेलखंड)→खान बहादुर खाँ, प्रयागराज (इलाहाबाद)→मौलवी लियाकत अली, फैजाबाद→मौलवी अहमदुल्ला शाह)।"},
  {"q":"1857 के महासंग्राम में बिहार के जगदीशपुर (आरा) से विद्रोह का नेतृत्व किसने किया?","options":["मौलवी अहमदुल्ला शाह","बाबू कुँवर सिंह","नाना साहेब एवं तात्या टोपे","बेगम हजरत महल"],"correct":1,"explanation":"1857 में जगदीशपुर के 80 वर्षीय जमींदार बाबू कुँवर सिंह ने अंग्रेजों को कई बार हराया। उनकी मृत्यु के बाद भाई अमर सिंह ने कैमूर पहाड़ियों से छापामार युद्ध जारी रखा।"},
  {"q":"1857 के विद्रोह में प्रयागराज (इलाहाबाद) व बनारस क्षेत्र का प्रमुख नेतृत्व किसने किया?","options":["बाबू कुँवर सिंह","नाना साहेब एवं तात्या टोपे","मौलवी लियाकत अली","बेगम हजरत महल"],"correct":2,"explanation":"इलाहाबाद में मौलवी लियाकत अली ने विद्रोह का नेतृत्व किया जिसे कर्नल नील ने क्रूरता से कुचला। असम में मणिराम दीवान व उड़ीसा में सुरेंद्र साई ने विद्रोह का बिगुल फूँका।"},
  {"q":"[UPSC Prelims पैटर्न — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लखनऊ (अवध) : मौलवी लियाकत अली\n2. प्रयागराज (इलाहाबाद) : नाना साहेब एवं तात्या टोपे\n3. कानपुर : बाबू कुँवर सिंह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: लखनऊ (अवध) — बेगम हजरत महल)। युग्म 2 गलत (सही: प्रयागराज (इलाहाबाद) — मौलवी लियाकत अली)। युग्म 3 गलत (सही: कानपुर — नाना साहेब एवं तात्या टोपे)।"},
  {"q":"[UPSC Prelims पैटर्न — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लखनऊ (अवध) : बेगम हजरत महल\n2. बरेली (रुहेलखंड) : खान बहादुर खाँ\n3. फैजाबाद : बाबू कुँवर सिंह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (बेगम हजरत महल ने 1857 में लखनऊ में विद्रोह की कमान संभाली तथा अंततः नेपाल पलायन किया।) युग्म 2 सही (बरेली में खान बहादुर खाँ ने स्वतंत्र सरकार की स्थापना कर 40,000 सैनिक जुटाए।) युग्म 3 गलत (सही: फैजाबाद — मौलवी अहमदुल्ला शाह)।"},
  {"q":"ऐतिहासिक संदर्भ में 'कानपुर (नाना साहेब व तात्या टोपे — कॉलिन कैम्पबेल दमन); लखनऊ (बेगम हजरत महल — कैम्पबेल); झाँसी/ग्वालियर (रानी लक्ष्मीबाई — ह्यूरोज); जगदीशपुर/आरा (बाबू कुँवर सिंह — विलियम टेलर); फैजाबाद (मौलवी अहमदुल्ला); बरेली (खान बहादुर)' (केंद्र व नेता युग्म) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["1857 के प्रमुख केंद्र, भारतीय नेतृत्व व ब्रिटिश दमनकर्ता","1857 विद्रोह पर इतिहासकारों के मत व 1858 के परिणाम","1857 की क्रांति की शुरुआत: मंगल पांडे, मेरठ व दिल्ली","पुर्तगाली शक्ति का आगमन: वास्को डी गामा, अल्मीडा व अल्बुकर्क"],"correct":0,"explanation":"फैजाबाद के मौलवी अहमदुल्ला शाह की गिरफ्तारी पर अंग्रेजों ने 50,000 रुपये का इनाम रखा था (रस्में जिहाद घोषित की); असम में मणिराम दीवान ने नेतृत्व किया।"},
  {"q":"[UPSC Prelims पैटर्न — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लखनऊ (अवध) : बेगम हजरत महल\n2. प्रयागराज (इलाहाबाद) : खान बहादुर खाँ\n3. बरेली (रुहेलखंड) : बाबू कुँवर सिंह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (बेगम हजरत महल ने 1857 में लखनऊ में विद्रोह की कमान संभाली तथा अंततः नेपाल पलायन किया।) युग्म 2 गलत (सही: प्रयागराज (इलाहाबाद) — मौलवी लियाकत अली)। युग्म 3 गलत (सही: बरेली (रुहेलखंड) — खान बहादुर खाँ)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — संवैधानिक अधिनियम एवं प्रावधान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. रेगुलेटिंग एक्ट, 1773   |   1. भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\nB. भारत शासन अधिनियम, 1935   |   2. गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\nC. चार्टर अधिनियम, 1813   |   3. संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\nD. चार्टर अधिनियम, 1833   |   4. अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण","options":["A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3"],"correct":2,"explanation":"सही सुमेलन: रेगुलेटिंग एक्ट, 1773 (गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ), भारत शासन अधिनियम, 1935 (अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण), चार्टर अधिनियम, 1813 (भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष), चार्टर अधिनियम, 1833 (संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति))।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. चार्टर अधिनियम, 1833 : संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\n2. रेगुलेटिंग एक्ट, 1773 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\n3. भारतीय परिषद अधिनियम, 1909 : अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (1833 के चार्टर एक्ट से लॉर्ड विलियम बेंटिंक भारत के प्रथम गवर्नर-जनरल बने।) युग्म 2 सही (1773 के रेगुलेटिंग एक्ट से वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल बने व बंबई-मद्रास उनके अधीन हुए।) युग्म 3 गलत (सही: भारतीय परिषद अधिनियम, 1909 — मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: संवैधानिक अधिनियम एवं प्रावधान के अंतर्गत 'चार्टर अधिनियम, 1813' का ऐतिहासिक संबंध 'संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)' से था।\nकथन-2: 1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('चार्टर अधिनियम, 1813' का सही संबंध 'भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष' से था — 1813 के चार्टर एक्ट से यूरोपीय व्यापारियों व ईसाई मिशनरियों को भारत आने की अनुमति मिली।)। कथन-2 सत्य है (1809 की अमृतसर की संधि द्वारा रणजीत सिंह के राज्य की पूर्वी सीमा सतलज नदी निर्धारित हुई।)।"},
  {"q":"[PSC/CDS युग्म पहचान — 1857 क्रांति केंद्र एवं नेता] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. जगदीशपुर (आरा) : बेगम हजरत महल\n2. लखनऊ (अवध) : मौलवी अहमदुल्ला शाह\n3. बरेली (रुहेलखंड) : खान बहादुर खाँ\n4. फैजाबाद : मौलवी लियाकत अली","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: बरेली में खान बहादुर खाँ ने स्वतंत्र सरकार की स्थापना कर 40,000 सैनिक जुटाए। (अन्य सही युग्म: जगदीशपुर (आरा)→बाबू कुँवर सिंह, लखनऊ (अवध)→बेगम हजरत महल, फैजाबाद→मौलवी अहमदुल्ला शाह)।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. चार्टर अधिनियम, 1853 : अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण\n2. भारत शासन अधिनियम, 1935 : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\n3. भारतीय परिषद अधिनियम, 1909 : संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: चार्टर अधिनियम, 1853 — केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता)। युग्म 2 गलत (सही: भारत शासन अधिनियम, 1935 — अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण)। युग्म 3 गलत (सही: भारतीय परिषद अधिनियम, 1909 — मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य)।"},
  {"q":"किस अधिनियम द्वारा बंगाल के गवर्नर को 'बंगाल का गवर्नर-जनरल' बनाया गया तथा 1774 में कलकत्ता सर्वोच्च न्यायालय स्थापित हुआ?","options":["गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ","भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष","संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)","कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण"],"correct":0,"explanation":"1773 के रेगुलेटिंग एक्ट से वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल बने व बंबई-मद्रास उनके अधीन हुए। इसमें निजी व्यापार व उपहार स्वीकार करने पर भी रोक लगाई गई।"},
  {"q":"1857 की क्रांति में लखनऊ (अवध) से किसने अपने अवयस्क पुत्र बिरजिस कादर की ओर से नेतृत्व किया?","options":["बाबू कुँवर सिंह","नाना साहेब एवं तात्या टोपे","मौलवी अहमदुल्ला शाह","बेगम हजरत महल"],"correct":3,"explanation":"बेगम हजरत महल ने 1857 में लखनऊ में विद्रोह की कमान संभाली तथा अंततः नेपाल पलायन किया। लखनऊ विद्रोह का दमन कॉलिन कैंपबेल ने गोरखा रेजिमेंट की सहायता से किया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1833 के चार्टर एक्ट से लॉर्ड विलियम बेंटिंक भारत के प्रथम गवर्नर-जनरल बने।\nकथन-2: बाल गंगाधर तिलक ने मांडले जेल (बर्मा) में 6 वर्षों के कारावास के दौरान प्रसिद्ध दार्शनिक कर्मयोग ग्रंथ 'गीता रहस्य' मराठी में लिखा था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) 1833 के चार्टर एक्ट से लॉर्ड विलियम बेंटिंक भारत के प्रथम गवर्नर-जनरल बने। (2) बाल गंगाधर तिलक ने मांडले जेल (बर्मा) में 6 वर्षों के कारावास के दौरान प्रसिद्ध दार्शनिक कर्मयोग ग्रंथ 'गीता रहस्य' मराठी में लिखा था।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: नाना साहेब (धोंधू पंत) व तात्या टोपे (रामचंद्र पांडुरंग) ने कानपुर में क्रांति का नेतृत्व किया।\nकथन-2: गोपाल कृष्ण गोखले ने निस्वार्थ देशसेवकों के प्रशिक्षण हेतु 1905 में यह संस्था बनाई।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) नाना साहेब (धोंधू पंत) व तात्या टोपे (रामचंद्र पांडुरंग) ने कानपुर में क्रांति का नेतृत्व किया। (2) गोपाल कृष्ण गोखले ने निस्वार्थ देशसेवकों के प्रशिक्षण हेतु 1905 में यह संस्था बनाई।"},
  {"q":"[PSC/CDS युग्म पहचान — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\n2. चार्टर अधिनियम, 1813 : संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\n3. चार्टर अधिनियम, 1853 : केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता\n4. चार्टर अधिनियम, 1833 : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: 1853 का चार्टर एक्ट चार्टर श्रृंखला का अंतिम अधिनियम था जिसने कंपनी के शासन की कोई निश्चित अवधि तय नहीं की। (अन्य सही युग्म: भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)→प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली, चार्टर अधिनियम, 1813→भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष, चार्टर अधिनियम, 1833→संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति))।"},
  {"q":"किस चार्टर एक्ट ने चाय व चीन व्यापार को छोड़कर कंपनी का भारतीय व्यापारिक एकाधिकार समाप्त कर शिक्षा पर ₹1 लाख वार्षिक प्रावधान किया?","options":["भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष","कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)","गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ"],"correct":0,"explanation":"1813 के चार्टर एक्ट से यूरोपीय व्यापारियों व ईसाई मिशनरियों को भारत आने की अनुमति मिली। 20 वर्षों बाद 1833 के अधिनियम ने चाय और चीन के साथ एकाधिकार भी पूरी तरह समाप्त कर दिया।"}
]);
